class _FactoryLocationEditorDialogState
    extends State<_FactoryLocationEditorDialog> {
  late final TextEditingController _name;
  late Set<String> _selected;

  @override
  void initState() {
    super.initState();
    _name = TextEditingController(text: widget.location?.name ?? '');
    _selected =
        widget.location?.apparatus.map((item) => item.id).toSet() ?? <String>{};
  }

  @override
  void dispose() {
    _name.dispose();
    super.dispose();
  }

  Future<void> _openApparatusPicker() async {
    final selected = await showModalBottomSheet<Set<String>>(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) => _ApparatusPickerBottomSheet(
        apparatus: widget.apparatus,
        initialSelected: _selected,
      ),
    );
    if (!mounted || selected == null) {
      return;
    }
    setState(() => _selected = selected);
  }

  List<AdminApparatus> get _selectedApparatus => widget.apparatus
      .where((item) => _selected.contains(item.id))
      .toList(growable: false);

  void _save() {
    final name = _name.text.trim();
    if (name.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(context.l10n.adminText('factory.enter_state_name')),
        ),
      );
      return;
    }
    Navigator.of(context).pop(
      _FactoryLocationEditorResult(
        name: name,
        apparatusIds: _selected.toList(growable: false),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final selectedApparatus = _selectedApparatus;
    return AlertDialog(
      insetPadding: const EdgeInsets.symmetric(horizontal: 20, vertical: 24),
      title: Text(
        widget.location == null
            ? context.l10n.adminText('factory.state_create')
            : context.l10n.adminText('factory.state_edit'),
      ),
      content: SizedBox(
        width: double.maxFinite,
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(
              controller: _name,
              autofocus: widget.location == null,
              readOnly: widget.location != null,
              textInputAction: TextInputAction.next,
              decoration: InputDecoration(
                labelText: context.l10n.adminText('factory.state_name'),
                border: OutlineInputBorder(),
              ),
            ),
            if (widget.location != null) ...[
              const SizedBox(height: 6),
              Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  context.l10n.adminText(
                    'factory.state_id_note',
                    values: {'id': widget.location!.id},
                  ),
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              ),
            ],
            const SizedBox(height: 12),
            SizedBox(
              width: double.infinity,
              child: OutlinedButton.icon(
                onPressed: _openApparatusPicker,
                icon: const Icon(Icons.add_link_rounded),
                label: Text(context.l10n.adminText('factory.attach_title')),
              ),
            ),
            const SizedBox(height: 8),
            if (selectedApparatus.isEmpty)
              Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  context.l10n.adminText('factory.no_equipment_linked'),
                  style: Theme.of(context).textTheme.bodySmall,
                ),
              )
            else
              Align(
                alignment: Alignment.centerLeft,
                child: Wrap(
                  spacing: 6,
                  runSpacing: 4,
                  children: [
                    for (final item in selectedApparatus)
                      InputChip(
                        label: Text(item.name),
                        onDeleted: () =>
                            setState(() => _selected.remove(item.id)),
                      ),
                  ],
                ),
              ),
            const SizedBox(height: 18),
            SizedBox(
              width: double.infinity,
              child: FilledButton(
                onPressed: _save,
                style: FilledButton.styleFrom(
                  minimumSize: const Size.fromHeight(52),
                ),
                child: Text(context.l10n.adminText('action.save')),
              ),
            ),
            const SizedBox(height: 6),
            SizedBox(
              width: double.infinity,
              child: TextButton(
                onPressed: () => Navigator.of(context).pop(),
                style: TextButton.styleFrom(
                  minimumSize: const Size.fromHeight(52),
                ),
                child: Text(context.l10n.adminText('action.cancel')),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

